// =====================================================================================
//  SHIFTERS - L6Builder.cs   [CH03 PERFORMANCE REVIEW: BOSS #1 THE DOWNSIZER]   LevelCatalog index 5
//  Loading Yard B on the factory roof (grey sky). Everything is code (regenerated by BuildAll).
//    S0  HR WAITING ROOM  x -7..7, z -8..8: spawn, TOOL LOCKER (BIT-SHIFTER), ticket dispenser, ME-TV, C1, gate (z 8)
//    ARENA                x -14..14, z 10..42 (ONE floor collider, 5 m walls, no pits): the press on its plinth at
//                         (0, 26), 4 stamp pads (N/E/S/W, 6 m from the column), 4 BREAK AREAS (C2 SW = P1, C3 SE = P2,
//                         C4 NW = P3, NE), supply chute (2 Shiftable crates, west), block bay (160 kg block, east),
//                         valve run (V1 button west, V2/V3 WindowGates along z 35.5), PIGMENT MAIN (east), north door
//    S4  BREAK ROOM ANNEX x -5..5, z 42..52: Percy, whiteboard, vending machine, C04 trigger, exit "STAIRS TO THE BANK"
//  Weight arithmetic (LEVELS2 0.1): crate 25 kg -> HUGE 100 kg (Brute only: 100 <= 114; non-Brutes <= 90) jams (>= 90);
//  block 160 kg (Brute push) jams; review scale 210 kg: all three 220-260 OK, any two <= 195 never.
// =====================================================================================
using UnityEngine;

namespace Shifters
{
    public class L6Builder : ILevelBuilder
    {
        public int LevelIndex => 5;

        // ---- metrics shared with the solution / tests
        public static readonly Vector3 Column = new Vector3(0f, 0f, 26f);
        public static readonly Vector3[] PadPos = { new Vector3(0f, 0f, 32f), new Vector3(6f, 0f, 26f), new Vector3(0f, 0f, 20f), new Vector3(-6f, 0f, 26f) };
        public static readonly string[] PadIds = { "N", "E", "S", "W" };
        public static readonly Vector3[] BreakPos = { new Vector3(-10.5f, 0f, 12.5f), new Vector3(10.5f, 0f, 12.5f), new Vector3(-10.5f, 0f, 39.5f), new Vector3(10.5f, 0f, 39.5f) };
        public static readonly Vector3 CrateA = new Vector3(-12f, 0f, 25f), CrateB = new Vector3(-12f, 0f, 27f), BlockPos = new Vector3(11f, 0f, 26f);
        public static readonly Vector3 ValveButton = new Vector3(-12f, 0f, 30f), ValveCorner = new Vector3(-12f, 0f, 35.5f),
                                       Valve2 = new Vector3(-2f, 0f, 35.5f), Valve3 = new Vector3(8.5f, 0f, 35.5f);
        public const float WallH = 5f, ValveRoute = 26f, ReviewKg = 210f;

        static readonly Color Orange = new Color(1f, 0.55f, 0.12f);
        static readonly Color Paper = new Color(0.95f, 0.93f, 0.86f);

        LevelBuildContext _ctx;
        L6DownsizerBoss _boss;
        BossArena _arena;

        public void Build(LevelBuildContext ctx)
        {
            _ctx = ctx;
            BuildS0();
            BuildArena();
            BuildPress();
            BuildPhaseParts();
            BuildAnnex();
            BuildWorld();
            var dir = Kit.Make("L6ChapterDirector", ctx.Gameplay, Vector3.zero).AddComponent<L6ChapterDirector>();
            dir.Boss = _boss;
            dir.Whiteboard = _annexBoard;
        }

        // ================================================================== helpers
        static Quaternion Facing(Vector3 towardViewer) => EnvKit.FacingViewer(towardViewer);
        static readonly Quaternion FloorRead = Quaternion.Euler(90f, 0f, 0f);   // flat on the floor, readable walking +Z

        GameObject WallSign(Transform t, Vector3 pos, Vector3 towardViewer, string text, float w, float h, SignStyle style = SignStyle.Info)
            => EnvKit.Sign(t, pos, Facing(towardViewer), text, new Vector2(w, h), style);

        void Wall(Transform t, Vector3 a, Vector3 b, float h = WallH, MatKey mat = MatKey.Wall) => EnvKit.Wall(t, a, b, h, 0.6f, mat);

        TMPro.TextMeshPro FloorText(Transform t, Vector3 pos, string text, float h, Color c, float width = 6f, float yaw = 0f)
            => _ctx.Label(t, pos + Vector3.up * 0.035f, Quaternion.Euler(90f, yaw, 0f), text, h, c, width);

        // ================================================================== S0 HR WAITING ROOM
        void BuildS0()
        {
            var ctx = _ctx;
            var s0 = ctx.Section("S0_HRWaitingRoom", Vector3.zero);
            ctx.Platform(ctx.Geometry, new Vector3(0f, 0f, 1f), new Vector3(14f, 1f, 18f), MatKey.Floor, true, "S0_Floor");     // z -8..10
            Wall(s0, new Vector3(-7.3f, 0f, -8.3f), new Vector3(7.3f, 0f, -8.3f), 4.5f);
            Wall(s0, new Vector3(-7.3f, 0f, -8.3f), new Vector3(-7.3f, 0f, 8.3f), 4.5f, MatKey.WallAlt);
            Wall(s0, new Vector3(7.3f, 0f, -8.3f), new Vector3(7.3f, 0f, 8.3f), 4.5f, MatKey.WallAlt);
            Wall(s0, new Vector3(-7.3f, 0f, 8.3f), new Vector3(-2.3f, 0f, 8.3f), 4.5f);
            Wall(s0, new Vector3(2.3f, 0f, 8.3f), new Vector3(7.3f, 0f, 8.3f), 4.5f);
            Wall(s0, new Vector3(-2.3f, 0f, 8.3f), new Vector3(-2.3f, 0f, 9.7f), WallH, MatKey.WallAlt);              // gate passage z 8..10
            Wall(s0, new Vector3(2.3f, 0f, 8.3f), new Vector3(2.3f, 0f, 9.7f), WallH, MatKey.WallAlt);
            ctx.Block(s0, new Vector3(0f, 4.7f, 8.3f), new Vector3(5.2f, 0.4f, 0.6f), MatKey.SafetyOrange, "GateLintel");

            ctx.SetSpawn(new Vector3(0f, 0f, -5f), 0f);
            ctx.Checkpoint(new Vector3(0f, 0f, 4f), 0f, 1);

            // TOOL LOCKER: BIT-SHIFTER (east wall, faces the room)
            var lockerPos = new Vector3(5.6f, 0f, 0f);
            var locker = WeaponKit.ToolLocker(ctx.Gameplay, lockerPos, EnvKit.FacingViewerAt(lockerPos, new Vector3(0f, 0f, 0f)), ExperimentalVariant.BitShifter);
            ctx.Mark("s0.locker", locker.gameObject);
            ctx.MarkPoint("s0.locker.stand", new Vector3(4.2f, 0f, 0f), 90f);
            WallSign(s0, new Vector3(7f, 3.1f, 0f), Vector3.left, "UPSIZER™ — EXPERIMENTAL.\n<size=70%>DO NOT POINT AT HR.</size>", 2.8f, 0.9f, SignStyle.Warning);
            ctx.Tutorial(new Vector3(4.2f, 1.5f, 0f), new Vector3(4.5f, 3f, 5f), "ch03_tools", "TOOL LOCKER",
                "TOOL LOCKER: swap your team's gun for this level's tool. Your gun waits here. Promise.", new[] { "E" }, false);

            // ticket dispenser (there is only one number)
            var disp = Kit.Make("TicketDispenser", s0, new Vector3(-5.6f, 0f, 1.5f));
            Kit.SolidBox(disp.transform, "Post", new Vector3(0f, 0.6f, 0f), new Vector3(0.5f, 1.2f, 0.5f), MatKey.MetalDark);
            Kit.BoxVisual(disp.transform, "Head", new Vector3(0f, 1.45f, 0f), new Vector3(0.7f, 0.5f, 0.6f), MatKey.WarningRed);
            Kit.BoxVisual(disp.transform, "Ticket", new Vector3(0.36f, 1.3f, 0f), new Vector3(0.02f, 0.16f, 0.12f), MatKey.SignWhite, 0f);
            WallSign(s0, new Vector3(-7f, 2.6f, 1.5f), Vector3.right, "DOWNSIZING DEPT.\n<size=60%>TAKE A NUMBER (THERE IS ONLY ONE)</size>", 3.2f, 1.1f);
            ctx.Label(disp.transform, new Vector3(0f, 2.05f, 0f), EnvKit.FacingViewer(Vector3.right), "NOW SERVING: 1", 0.26f, UIColors.AccentYellow, 2f);

            // waiting room furniture
            EnvKit.Decor.Bench(s0, new Vector3(-4.5f, 0f, -4f), EnvKit.FacingViewer(Vector3.right), 2.4f);
            EnvKit.Decor.Bench(s0, new Vector3(-4.5f, 0f, -1.2f), EnvKit.FacingViewer(Vector3.right), 2.4f);
            EnvKit.Decor.Plant(s0, new Vector3(-6.3f, 0f, -7.2f), 0);
            EnvKit.Decor.Plant(s0, new Vector3(6.3f, 0f, -7.2f), 1);
            EnvKit.Decor.DeskWithMonitors(s0, new Vector3(4.6f, 0f, -5.2f), EnvKit.FacingViewer(Vector3.left));
            ctx.Label(s0, new Vector3(4.6f, 1.95f, -5.2f), EnvKit.FacingViewer(Vector3.left), "RECEPTION (UNSTAFFED)", 0.24f, UIColors.TextMuted, 3f);

            // story dressing: ME-TV + posters + signs
            StoryKit.MeTvScreen(ctx.Decor, new Vector3(0f, 3.1f, -8f), Facing(Vector3.forward), 4f);
            StoryKit.HoloPoster(ctx.Decor, new Vector3(-6.4f, 0f, 5.8f), Facing(Vector3.right), "TWO'S A CROWD. THREE'S A CRIME.", 1);
            StoryKit.HoloPoster(ctx.Decor, new Vector3(6.4f, 0f, 5.8f), Facing(Vector3.left), "HIGH-FIVES ARE LIMITED TO ONE (1) HAND.", 1);
            EnvKit.Poster(s0, new Vector3(-3.6f, 2.4f, -8f), Facing(Vector3.forward), "EMPLOYEE OF THE MONTH", "THE PRESS", new Vector2(1.6f, 2.0f));
            EnvKit.Poster(s0, new Vector3(3.6f, 2.4f, -8f), Facing(Vector3.forward), "PERFORMANCE REVIEWS", "NOW 100% HYDRAULIC", new Vector2(1.6f, 2.0f));
            WallSign(s0, new Vector3(0f, 3.75f, 8f), Vector3.back, "LOADING YARD B — PERFORMANCE REVIEW IN PROGRESS: YOU", 6.4f, 0.8f, SignStyle.Danger);

            // gate + the boss tutorial (important) + the intro trigger just inside the arena
            ctx.Tutorial(new Vector3(0f, 1.5f, 8.6f), new Vector3(4f, 3f, 2.6f), "ch03_boss", "BOSS FIGHT",
                "BOSSES ONLY SEE WHO YOU'RE CONTROLLING. Park the others in BREAK AREAS. Open the wheel to slow time.", new[] { "RShift" }, true);
            StoryKit.ScriptTrigger(ctx.Gameplay, new Vector3(0f, 1.5f, 11.6f), new Vector3(8f, 3f, 2f), "ch03.intro", true);
            ctx.MarkPoint("s1.enter", new Vector3(0f, 0f, 13f), 0f);
        }

        // ================================================================== ARENA shell
        void BuildArena()
        {
            var ctx = _ctx;
            var a = ctx.Section("Arena", Vector3.zero);
            ctx.Platform(ctx.Geometry, new Vector3(0f, 0f, 26f), new Vector3(28f, 1f, 32f), MatKey.Concrete, false, "Arena_Floor");   // ONE floor collider
            _arena = BossKit.Arena(ctx.Gameplay, Column, new Vector2(28f, 32f), 0f, false);
            // walls (own build: gate + door openings), 5 m
            Wall(a, new Vector3(-14.3f, 0f, 9.7f), new Vector3(-14.3f, 0f, 42.3f), WallH, MatKey.WallAlt);
            Wall(a, new Vector3(14.3f, 0f, 9.7f), new Vector3(14.3f, 0f, 42.3f), WallH, MatKey.WallAlt);
            Wall(a, new Vector3(-14.3f, 0f, 9.7f), new Vector3(-2.3f, 0f, 9.7f));
            Wall(a, new Vector3(2.3f, 0f, 9.7f), new Vector3(14.3f, 0f, 9.7f));
            Wall(a, new Vector3(-14.3f, 0f, 42.3f), new Vector3(-2.3f, 0f, 42.3f));
            Wall(a, new Vector3(2.3f, 0f, 42.3f), new Vector3(14.3f, 0f, 42.3f));
            ctx.Block(a, new Vector3(0f, 4.4f, 42.3f), new Vector3(5.2f, 1.2f, 0.6f), MatKey.SafetyOrange, "DoorLintel");
            foreach (var x in new[] { -14.3f, 14.3f }) foreach (var z in new[] { 9.7f, 42.3f }) EnvKit.Pillar(a, new Vector3(x, 0f, z), WallH + 0.6f, 1f);

            // break areas (also the phase checkpoints)
            string[] bn = { "SW", "SE", "NW", "NE" };
            for (int i = 0; i < 4; i++)
            {
                var ba = BossKit.BreakArea(_arena.transform, BreakPos[i] - Column, new Vector2(7f, 5f));
                ba.name = "BreakArea_" + bn[i];
                ctx.MarkPoint("boss.safe." + (i + 1), BreakPos[i], 0f);
            }
            var cps = new Checkpoint[3];
            for (int i = 0; i < 3; i++)
            {
                var cp = ctx.Checkpoint(BreakPos[i] + new Vector3(0f, 0f, i < 2 ? -0.2f : 0.2f), 0f, 2 + i);
                cps[i] = cp != null ? cp.GetComponentInChildren<Checkpoint>(true) : null;
            }
            _arena.PhaseCheckpoints = cps;
            WallSign(a, new Vector3(-10.5f, 3.4f, 10f), Vector3.forward, "BREAK AREA\n<size=60%>THE PRESS RESPECTS UNION BREAKS</size>", 3.4f, 1.1f, SignStyle.Warning);
            WallSign(a, new Vector3(10.5f, 3.4f, 10f), Vector3.forward, "BREAK AREA\n<size=60%>15 MINUTES. OR 15 SECONDS. HR DECIDES.</size>", 3.4f, 1.1f, SignStyle.Warning);
            WallSign(a, new Vector3(-10.5f, 3.4f, 42f), Vector3.back, "BREAK AREA\n<size=60%>THE PRESS RESPECTS UNION BREAKS</size>", 3.4f, 1.1f, SignStyle.Warning);
            WallSign(a, new Vector3(10.5f, 3.4f, 42f), Vector3.back, "BREAK AREA\n<size=60%>NO WORK. NO PRESS. NO KIDDING.</size>", 3.4f, 1.1f, SignStyle.Warning);

            // story dressing in the arena
            StoryKit.MeTvScreen(ctx.Decor, new Vector3(0f, 6.6f, 42.4f), Facing(Vector3.back), 4.4f);
            StoryKit.HoloPoster(ctx.Decor, new Vector3(-13.4f, 0f, 18.5f), Facing(Vector3.right), "REPORT ALL COOPERATION TO: ME", 1);
            StoryKit.HoloPoster(ctx.Decor, new Vector3(13.4f, 0f, 18.5f), Facing(Vector3.left), "THERE'S NO TEAM IN 'ME'.", 1);
            StoryKit.HoloPoster(ctx.Decor, new Vector3(13.4f, 0f, 33.5f), Facing(Vector3.left), "SOLO IS THE NEW TOGETHER.", 1);
            WallSign(a, new Vector3(-6.5f, 3.6f, 10f), Vector3.forward, "PERFORMANCE REVIEW IN PROGRESS: YOU", 4.4f, 0.75f, SignStyle.Danger);

            // IQ clue: press maintenance whiteboard (SW break area wall)
            var wb = EnvKit.Decor.Whiteboard(a, new Vector3(-13.95f, 1.6f, 15.5f), Facing(Vector3.right), "PRESS MAINTENANCE\n1 JAM IT (90 KG)\n2 VALVES (FAST)\n3 OVERLOAD (3 STAFF)");
            PerspectiveKit.Reveal(wb, PerspectiveMask.Intellect, "PRESS MAINTENANCE: 1 JAM IT · 2 VALVES · 3 OVERLOAD (3 STAFF)", true, false, new Vector3(0f, 1.4f, 0f));
        }

        // ================================================================== the press, pads, heart
        void BuildPress()
        {
            var ctx = _ctx;
            var model = BossModels.Downsizer(ctx.Gameplay, Column, Quaternion.identity, true, true);
            model.name = "DownsizerModel";
            if (model.StampCollider != null) model.StampCollider.enabled = false;
            model.SetArmYaw(0f); model.SetStampBottom(L6DownsizerBoss.RestBottom); model.SetShutter(0f);

            var bossGo = Kit.Make("THE DOWNSIZER", ctx.Gameplay, Column);
            _boss = bossGo.AddComponent<L6DownsizerBoss>();
            _boss.Configure();
            _boss.Arena = _arena;
            _boss.Body = bossGo.transform;
            _boss.Model = model;
            ctx.Mark("boss", bossGo);

            BossKit.Mark(_arena, "Column", Vector3.zero);
            var pads = new Transform[4];
            var lamps = new Renderer[4];
            string[] names = { "padN", "padE", "padS", "padW" };
            for (int i = 0; i < 4; i++)
            {
                BossKit.Mark(_arena, names[i], PadPos[i] - Column);
                var pad = Kit.Make("StampPad_" + PadIds[i], ctx.Puzzles, PadPos[i]);
                var t = pad.transform;
                pads[i] = t;
                Kit.BoxVisual(t, "Plate", new Vector3(0f, 0.01f, 0f), new Vector3(3f, 0.02f, 3f), MatKey.MetalDark, 0f, null, false);
                foreach (var e in new[] { new Vector4(0f, 1.38f, 3f, 0.24f), new Vector4(0f, -1.38f, 3f, 0.24f), new Vector4(1.38f, 0f, 0.24f, 3f), new Vector4(-1.38f, 0f, 0.24f, 3f) })
                    Kit.BoxVisual(t, "Stripe", new Vector3(e.x, 0.025f, e.y), new Vector3(e.z, 0.02f, e.w), MatKey.HazardStripes, 0f, null, false);
                var outward = (PadPos[i] - Column).normalized;
                var lampPos = outward * 2.1f + new Vector3(outward.z, 0f, -outward.x) * 1.6f;
                Kit.BoxVisual(t, "LampPost", lampPos + new Vector3(0f, 0.5f, 0f), new Vector3(0.18f, 1f, 0.18f), MatKey.MetalDark, 0.02f);
                Kit.BoxVisual(t, "LampOff", lampPos + new Vector3(0f, 1.12f, 0f), new Vector3(0.34f, 0.24f, 0.34f), MatKey.LightOff, 0.03f);
                lamps[i] = Kit.BoxVisual(t, "LampOn", lampPos + new Vector3(0f, 1.12f, 0f), new Vector3(0.38f, 0.28f, 0.38f), MatKey.LightRed, 0.03f, null, false);
                lamps[i].enabled = false;
                float yaw = Mathf.Atan2(outward.x, outward.z) * Mathf.Rad2Deg;   // text reads from the outer side
                FloorText(t, outward * 0.55f, "YOUR POSITION HAS BEEN ELIMINATED\n<size=70%>(PLEASE STAND ON IT)</size>", 0.2f, Paper, 2.8f, yaw + 180f);
                FloorText(t, -outward * 0.75f, "PAD " + PadIds[i], 0.4f, UIColors.AccentYellow, 2.4f, yaw + 180f);
                PerspectiveKit.Reveal(pad, PerspectiveMask.Strength, "JAMS AT ≥ 90 KG", true, false, new Vector3(0f, 1.6f, 0f));
                ctx.MarkPoint("s1.pad" + PadIds[i] + ".center", PadPos[i], 0f);
            }
            ctx.MarkPoint("s1.padW.drop", PadPos[3] + new Vector3(-0.9f, 0f, 0f), 90f);
            _boss.Pads = pads;
            _boss.PadLampsOn = lamps;

            // the HYDRAULIC HEART: shoot weak point (P1 + P2), the model's tank is the visual
            var heart = BossKit.WeakPointShoot(ctx.Gameplay, Column + model.HeartCenter, 0.6f, _boss, (1 << 0) | (1 << 1));
            foreach (var r in heart.GetComponentsInChildren<Renderer>(true)) if (r.name == "Core" || r.name == "Rim") r.enabled = false;
            _boss.Heart = heart;
            ctx.Mark("boss.weak.heart", heart.gameObject);
            // shooting spots for the gun / tool holder (off every pad, LOS to the heart ~9.5 m)
            ctx.MarkPoint("s1.shoot", new Vector3(-6.5f, 0f, 19f), 0f);
            ctx.MarkPoint("s2.shoot", new Vector3(6.5f, 0f, 19f), 0f);

            // review scale (P3) on the stamp
            var scaleGo = Kit.Make("ReviewScale", ctx.Puzzles, PadPos[2]);
            var sensor = scaleGo.AddComponent<WeightSensor>();
            sensor.Surfaces = model.StampCollider != null ? new Collider[] { model.StampCollider } : new Collider[0];
            var scale = scaleGo.AddComponent<L6ReviewScale>();
            scale.Sensor = sensor; scale.RequiredKg = ReviewKg; scale.HoldSeconds = 2f;
            scale.SolvedMessage = "OVERLOAD!";
            _boss.Scale = scale;
            ctx.Mark("s3.scale", scaleGo);
            if (model.Stamp != null)
            {
                var lbl = _ctx.Label(model.Stamp, new Vector3(0f, model.StampThickness + 0.03f, -0.9f), Quaternion.Euler(90f, 180f, 0f), "REVIEW SCALE", 0.3f, UIColors.AccentYellow, 3.2f);
                _boss.ScaleLabel = lbl;
            }
            PerspectiveKit.Reveal(scaleGo, PerspectiveMask.Strength, "OVERLOADS AT ≥ 210 KG (RATED 150)", true, true, new Vector3(0f, 2.2f, 0f));
            ctx.MarkPoint("s3.plate.a", PadPos[2] + new Vector3(-0.9f, 0.5f, -0.6f), 0f);
            ctx.MarkPoint("s3.plate.b", PadPos[2] + new Vector3(0.9f, 0.5f, -0.6f), 0f);
            ctx.MarkPoint("s3.plate.c", PadPos[2] + new Vector3(0f, 0.5f, 0.8f), 0f);
            ctx.MarkPoint("s3.approach.a", new Vector3(-0.9f, 0f, 16.6f), 0f);
            ctx.MarkPoint("s3.approach.b", new Vector3(0.9f, 0f, 16.6f), 0f);
            ctx.MarkPoint("s3.approach.c", new Vector3(0f, 0f, 16.4f), 0f);
            ctx.MarkPoint("s3.lane.e", new Vector3(9.5f, 0f, 17f), 0f);
            ctx.MarkPoint("s3.lane.w", new Vector3(-5f, 0f, 16f), 0f);
            ctx.MarkPoint("s4.path.1", new Vector3(-4.6f, 0f, 21.5f), 0f);
            ctx.MarkPoint("s4.path.2", new Vector3(-5f, 0f, 38.6f), 0f);
            ctx.MarkPoint("s4.door", new Vector3(0f, 0f, 40.5f), 0f);
            // HR-approved step stool south of pad S (the platform top is 0.5 m)
            ctx.Block(ctx.Geometry, PadPos[2] + new Vector3(0f, 0.12f, -2.25f), new Vector3(2.2f, 0.24f, 0.6f), MatKey.SafetyOrange, "StepStool");
            FloorText(ctx.Decor, PadPos[2] + new Vector3(0f, 0.24f, -2.25f), "STEP STOOL · HR APPROVED · 1 EMPLOYEE", 0.13f, UIColors.Text, 2.1f);

            // PIGMENT MAIN (east wall) + the overhead branch the press topples into
            var pipeT = ctx.Section("PigmentMain", Vector3.zero);
            EnvKit.Pipe(pipeT, new[] { new Vector3(13.6f, 3.4f, 10.5f), new Vector3(13.6f, 3.4f, 41.5f) }, 0.38f, false, MatKey.Pipe);
            EnvKit.Pipe(pipeT, new[] { new Vector3(13.6f, 3.4f, 26f), new Vector3(13.6f, 4.6f, 26f), new Vector3(8.4f, 4.6f, 26f) }, 0.26f, false, MatKey.Pipe);
            for (int i = 0; i < 6; i++) Kit.BoxVisual(pipeT, "OrangeBand", new Vector3(13.6f, 3.4f, 13f + i * 5.5f), new Vector3(0.84f, 0.84f, 0.3f), MatKey.SafetyOrange, 0.05f, null, false);
            Kit.BoxVisual(pipeT, "BranchValve", new Vector3(8.3f, 4.6f, 26f), new Vector3(0.5f, 0.9f, 0.9f), MatKey.SafetyOrange, 0.08f, null, false);
            WallSign(pipeT, new Vector3(14f, 2.1f, 22f), Vector3.left, "PIGMENT MAIN — ORANGE\n<size=60%>DO NOT TOPPLE HEAVY MACHINERY ONTO THIS PIPE</size>", 3.6f, 1.0f, SignStyle.Warning);
            _boss.PipePoint = ctx.MarkPoint("s3.pipe", new Vector3(8.3f, 4.6f, 26f), 0f);
        }

        // ================================================================== phase parts: props, valves, hints, door
        void BuildPhaseParts()
        {
            var ctx = _ctx;
            var a = ctx.Section("PhaseParts", Vector3.zero);

            // P1 props: supply chute (west) + block bay (east)
            var crateA = PuzzleKit.Crate(ctx.Props, CrateA);
            var crateB = PuzzleKit.Crate(ctx.Props, CrateB);
            PuzzleKit.MakeShiftable(crateA); PuzzleKit.MakeShiftable(crateB);
            PerspectiveKit.Reveal(crateA.gameObject, PerspectiveMask.Strength, "25 KG · HUGE = 100 KG (HEAVY LIFTER)", true, true, new Vector3(0f, 1.2f, 0f));
            PerspectiveKit.Reveal(crateB.gameObject, PerspectiveMask.Strength, "25 KG · HUGE = 100 KG (HEAVY LIFTER)", true, true, new Vector3(0f, 1.2f, 0f));
            ctx.Mark("s1.crateA", crateA.gameObject);
            ctx.Mark("s1.crateB", crateB.gameObject);
            ctx.MarkPoint("s1.crate.shoot", new Vector3(-8f, 0f, 22.5f), -60f);
            var block = PuzzleKit.HeavyBlock(ctx.Props, BlockPos);
            ctx.Mark("s1.block", block.gameObject);
            _boss.Props = new[] { crateA, crateB, block.GetComponent<Rigidbody>() };

            var chute = ctx.Section("SupplyChute", Vector3.zero);
            Kit.BoxVisual(chute, "ChuteFrame", new Vector3(-13.9f, 2.4f, 26f), new Vector3(0.3f, 0.3f, 4.2f), MatKey.SafetyOrange, 0.03f);
            Kit.BoxVisual(chute, "ChuteMouth", new Vector3(-13.95f, 1.2f, 26f), new Vector3(0.12f, 2.2f, 3.8f), MatKey.HazardBlack, 0f, null, false);
            WallSign(chute, new Vector3(-14f, 3.3f, 26f), Vector3.right, "SUPPLY CHUTE\n<size=60%>CRATES: 25 KG. JAMS AT 90. DO THE MATH.</size>", 3.4f, 1f, SignStyle.Info);
            var chuteHatch = Kit.Make("ChuteHatch_P3", chute, new Vector3(-13.2f, 0f, 26f));
            Kit.BoxVisual(chuteHatch.transform, "Shutter", new Vector3(0f, 1.2f, 0f), new Vector3(0.2f, 2.4f, 4.2f), MatKey.MetalLight, 0.03f);
            ctx.Label(chuteHatch.transform, new Vector3(0.12f, 1.4f, 0f), Facing(Vector3.right), "CLOSED\n<size=60%>HR PROPERTY</size>", 0.45f, UIColors.Danger, 3.6f);
            chuteHatch.SetActive(false);

            var bay = ctx.Section("BlockBay", Vector3.zero);
            Kit.BoxVisual(bay, "BayFrameN", new Vector3(12.6f, 0.02f, 27.4f), new Vector3(3f, 0.04f, 0.2f), MatKey.HazardStripes, 0f, null, false);
            Kit.BoxVisual(bay, "BayFrameS", new Vector3(12.6f, 0.02f, 24.6f), new Vector3(3f, 0.04f, 0.2f), MatKey.HazardStripes, 0f, null, false);
            for (int i = 0; i < 5; i++) Kit.BoxVisual(bay, "Chevron", new Vector3(9.7f - i * 0.75f, 0.02f, 26f), new Vector3(0.18f, 0.03f, 0.9f), MatKey.HazardYellow, 0f, Quaternion.Euler(0f, 35f, 0f), false);
            WallSign(bay, new Vector3(14f, 3.3f, 29.5f), Vector3.left, "BLOCK BAY\n<size=60%>160 KG. PUSH TO PAD E. LIFT WITH YOUR LEGS.</size>", 3.4f, 1f, SignStyle.Info);
            var lane = Kit.Make("PushLane", bay, new Vector3(8.5f, 0f, 26f));
            Kit.BoxVisual(lane.transform, "LaneDecal", new Vector3(0f, 0.012f, 0f), new Vector3(5f, 0.02f, 1.7f), MatKey.Grate, 0f, null, false);
            PerspectiveKit.Reveal(lane, PerspectiveMask.Strength, "160 KG → PAD E (BRUTE PUSH)", true, true, new Vector3(0f, 1.5f, 0f));
            var bayHatch = Kit.Make("BayHatch_P3", bay, new Vector3(12.6f, 0f, 26f));
            Kit.BoxVisual(bayHatch.transform, "Hatch", new Vector3(0f, 0.02f, 0f), new Vector3(2.6f, 0.04f, 2.6f), MatKey.HazardBlack, 0f, null, false);
            ctx.Label(bayHatch.transform, new Vector3(0f, 0.07f, 0f), FloorRead, "BLOCK RECALLED\n<size=60%>HR PROPERTY</size>", 0.35f, UIColors.Danger, 2.6f);
            bayHatch.SetActive(false);
            _boss.PropHatches = new[] { chuteHatch, bayHatch };
            ctx.Tutorial(new Vector3(-11f, 1.5f, 25.5f), new Vector3(6f, 3f, 7f), "ch03_bitshift", "BIT-SHIFTER",
                "BIT-SHIFTER: shoot a crate to make it HUGE. Shoot again: TINY. Again: normal.", new[] { "LMB" }, false);

            // P2 valve run: V1 TimedButton (route 26 m, TURBO only) -> V2 / V3 WindowGates -> ARMOR latch
            var route = new[] { ValveButton + Vector3.up * 0.05f, ValveCorner + Vector3.up * 0.05f, Valve2 + Vector3.up * 0.05f, Valve3 + Vector3.up * 0.05f };
            var v1 = PuzzleKit.TimedButton(ctx.Puzzles, ValveButton, Quaternion.identity, ValveRoute, route, "VALVE 1 OPEN");
            ctx.Mark("s2.v1", v1.gameObject);
            ctx.MarkPoint("s2.v1.stand", ValveButton + new Vector3(0f, 0f, 0.95f), 180f);
            var v2 = PuzzleKit.WindowGate(ctx.Puzzles, Valve2, Quaternion.Euler(0f, 90f, 0f), new Vector3(3f, 3f, 1f), v1);
            var v3 = PuzzleKit.WindowGate(ctx.Puzzles, Valve3, Quaternion.Euler(0f, 90f, 0f), new Vector3(3f, 3f, 1f), v1);
            ctx.Mark("s2.gate2", v2.gameObject); ctx.Mark("s2.gate3", v3.gameObject);
            ctx.MarkPoint("s2.corner", ValveCorner, 90f);
            ctx.MarkPoint("s2.approach", new Vector3(-9.6f, 0f, 31.4f), 0f);
            ctx.MarkPoint("s2.approach.s", new Vector3(-9.5f, 0f, 18.5f), 0f);
            ctx.MarkPoint("s1.lane.e", new Vector3(9.5f, 0f, 17f), 0f);
            ctx.MarkPoint("s1.block.behind", new Vector3(13.1f, 0f, 26f), -90f);
            ctx.MarkPoint("s2.v2", Valve2, 90f);
            ctx.MarkPoint("s2.v3", Valve3 + new Vector3(1.6f, 0f, 0f), 90f);
            var latchGo = Kit.Make("ArmorLatch", ctx.Puzzles, new Vector3(13.2f, 0f, 35.5f));
            var latch = latchGo.AddComponent<L6ValveLatch>();
            latch.Inputs = new SignalSource[] { v1, v2, v3 };
            latch.SolvedMessage = "ARMOR OPEN!";
            Kit.SolidBox(latchGo.transform, "Gauge", new Vector3(0f, 0.7f, 0f), new Vector3(0.6f, 1.4f, 0.6f), MatKey.MetalDark);
            var lit = Kit.BoxVisual(latchGo.transform, "GaugeLit", new Vector3(0f, 1.55f, 0f), new Vector3(0.5f, 0.3f, 0.5f), MatKey.LightOn, 0.03f, null, false);
            lit.enabled = false;
            latch.LitWhenOn = new Renderer[] { lit };
            _boss.Valves = latch;
            ctx.Mark("s2.armor", latchGo);
            ctx.Label(a, ValveButton + new Vector3(-1.4f, 2.7f, 0f), Facing(Vector3.right), "VALVE 1", 0.4f, UIColors.Speed, 2f);
            WallSign(a, new Vector3(-14f, 2.6f, 32.5f), Vector3.right, "VALVE RUN 26 M\n<size=60%>VALVES LIKE SPEED</size>", 2.8f, 1f, SignStyle.Arrow);
            for (int i = 0; i < 6; i++) Kit.BoxVisual(a, "ValveChevron", new Vector3(-8f + i * 3f, 0.02f, 35.5f), new Vector3(0.2f, 0.03f, 1.1f), MatKey.HazardYellow, 0f, Quaternion.Euler(0f, 35f, 0f), false);
            PerspectiveKit.Reveal(v1.gameObject, PerspectiveMask.Speed, "VALVE RUN 26 M · TURBO ONLY", true, false, new Vector3(0f, 2.2f, 0f));

            // hints, one per phase (the boss shows the current phase's zone)
            var arenaC = new Vector3(0f, 2.5f, 26f); var arenaS = new Vector3(28f, 5f, 32f);
            _boss.PhaseHints = new[]
            {
                ctx.Hint(arenaC, arenaS, "Make a crate HUGE; only the Brute can carry it onto a pad. Or push the block onto one.", "It can't crush what it can't crush."),
                ctx.Hint(arenaC, arenaS, "Only TURBO LEGS reach all three valves in time. Start at the west valve.", "Valves like speed."),
                ctx.Hint(arenaC, arenaS, "All three of you on the review plate. It's rated for one.", "Overload it. With people."),
            };

            // north door opens on defeat (boss = SignalSource ON)
            var door = PuzzleKit.Door(ctx.Puzzles, new Vector3(0f, 0f, 42.3f), Quaternion.identity, DoorMode.SlideUp, 4f, 3.8f, _boss);
            ctx.Mark("s3.door", door.gameObject);
            WallSign(a, new Vector3(0f, 4.55f, 42f), Vector3.back, "BREAK ROOM — STAFF ONLY (STAFF: NONE)", 4.4f, 0.55f, SignStyle.Exit);
        }

        // ================================================================== S4 BREAK ROOM ANNEX
        TMPro.TextMeshPro _annexBoard;
        void BuildAnnex()
        {
            var ctx = _ctx;
            var s4 = ctx.Section("S4_BreakRoomAnnex", Vector3.zero);
            ctx.Platform(ctx.Geometry, new Vector3(0f, 0f, 49.05f), new Vector3(10f, 1f, 13.5f), MatKey.FloorAlt, true, "S4_Floor");   // z 42.3..55.8
            Wall(s4, new Vector3(-5.3f, 0f, 42.3f), new Vector3(-5.3f, 0f, 56.1f), 5f, MatKey.WallAlt);
            Wall(s4, new Vector3(5.3f, 0f, 42.3f), new Vector3(5.3f, 0f, 56.1f), 5f, MatKey.WallAlt);
            Wall(s4, new Vector3(-5.3f, 0f, 56.1f), new Vector3(5.3f, 0f, 56.1f), 5f);
            ctx.MarkPoint("s4.annex", new Vector3(0f, 0f, 46f), 0f);

            StoryKit.PercyMachine(ctx.Decor, new Vector3(-3.4f, 0f, 47.5f), EnvKit.FacingViewerAt(new Vector3(-3.4f, 0f, 47.5f), new Vector3(0f, 0f, 46f)));
            ctx.MarkPoint("story.percy", new Vector3(-3.4f, 0f, 47.5f), 90f);
            var wb = EnvKit.Decor.Whiteboard(s4, new Vector3(4.95f, 1.6f, 47.5f), Facing(Vector3.left), "MEETING: ???\n(PERCY KNOWS)");
            _annexBoard = wb.GetComponentInChildren<TMPro.TextMeshPro>(true);
            if (_annexBoard == null) _annexBoard = ctx.Label(s4, new Vector3(4.85f, 1.6f, 47.5f), Facing(Vector3.left), "MEETING: ???", 0.24f, new Color(0.15f, 0.2f, 0.45f), 2.2f);
            var vend = Kit.Make("VendingMachine", s4, new Vector3(-4.2f, 0f, 54.2f), Quaternion.Euler(0f, -90f, 0f));
            Kit.SolidBox(vend.transform, "Body", new Vector3(0f, 1f, 0f), new Vector3(1.2f, 2f, 0.9f), MatKey.WarningRed);
            Kit.BoxVisual(vend.transform, "Glass", new Vector3(-0.1f, 1.15f, -0.46f), new Vector3(0.8f, 1.3f, 0.03f), MatKey.Screen, 0f, null, false);
            ctx.Label(vend.transform, new Vector3(0f, 2.2f, -0.47f), Facing(Vector3.back), "SNACKS FOR ONE (1)", 0.18f, UIColors.AccentYellow, 1.2f);
            EnvKit.Decor.Bench(s4, new Vector3(4.3f, 0f, 53.6f), Facing(Vector3.left), 2.2f);
            EnvKit.Decor.Plant(s4, new Vector3(-4.5f, 0f, 43.3f), 2);
            StoryKit.HoloPoster(ctx.Decor, new Vector3(4.4f, 0f, 44.4f), Facing(Vector3.left), "LUNCH: EAT ALONE. DIGEST ALONE.", 1);
            WallSign(s4, new Vector3(-5f, 3.3f, 45.0f), Vector3.right, "THE SOLO ACT\n<size=55%>ART. 1 ONE RULER · ART. 2 ONE CHAIR · ART. 3 [STICKY NOTE]</size>", 3.6f, 1.1f, SignStyle.Info);

            StoryKit.ScriptTrigger(ctx.Gameplay, new Vector3(0f, 1.5f, 45.6f), new Vector3(9f, 3f, 3f), "ch03.outro", true);
            ctx.Exit(new Vector3(0f, 0f, 51f), 0f);
            WallSign(s4, new Vector3(5f, 3.1f, 50.4f), Vector3.left, "STAIRS TO THE BANK →", 2.8f, 0.6f, SignStyle.Exit);
        }

